{"src/people/date.mjs":"export function validSurveyDate(value, today, allowToday) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + 'T00:00:00Z');
  if (!Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== value) return false;
  if (typeof today !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(today)) return false;
  const todayParsed = new Date(today + 'T00:00:00Z');
  if (!Number.isFinite(todayParsed.getTime()) || todayParsed.toISOString().slice(0, 10) !== today) return false;
  if (allowToday === true) return value <= today;
  return value < today;
}
","src/people/create.mjs":"import { validSurveyDate } from './date.mjs';
export function createPerson(record, today, allowToday) {
  if (!validSurveyDate(record.surveyDate, today, allowToday)) throw new Error('调查日期无效');
  return { ...record };
}
","src/people/import.mjs":"import { validSurveyDate } from './date.mjs';
export function importPeople(rows, today, allowToday) {
  const accepted = [], rejected = [];
  rows.forEach((row, i) => {
    if (validSurveyDate(row.surveyDate, today, allowToday)) accepted.push({ ...row });
    else rejected.push({ row: i + 1, reason: '调查日期无效' });
  });
  return { accepted, rejected };
}
"}
